use std::process::ExitCode;

use wgpu::util::DeviceExt;

const WORKGROUP: u32 = 16;

const SHADER: &str = r#"
struct Params {
    width: u32,
    height: u32,
    limit: u32,
    _pad: u32,
};

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read> xs: array<f32>;
@group(0) @binding(2) var<storage, read> ys: array<f32>;
@group(0) @binding(3) var<storage, read_write> times: array<u32>;

@compute @workgroup_size(16, 16, 1)
fn main(@builtin(global_invocation_id) id: vec3<u32>) {
    let i = id.x;
    let j = id.y;
    if (i >= params.width || j >= params.height) {
        return;
    }
    let cx = xs[i];
    let cy = ys[j];
    var zx: f32 = 0.0;
    var zy: f32 = 0.0;
    var n: u32 = 0u;
    loop {
        if (n >= params.limit || zx * zx + zy * zy > 4.0) {
            break;
        }
        let nx = zx * zx - zy * zy + cx;
        zy = 2.0 * zx * zy + cy;
        zx = nx;
        n = n + 1u;
    }
    times[j * params.width + i] = n;
}
"#;

struct Input {
    width: u32,
    height: u32,
    limit: u32,
    x_min: f64,
    x_max: f64,
    y_min: f64,
    y_max: f64,
}

fn parse_input(text: &str) -> Result<Input, String> {
    let mut lines = text.lines().filter(|l| !l.trim().is_empty());
    let first: Vec<&str> = lines
        .next()
        .ok_or("missing first line")?
        .split_whitespace()
        .collect();
    let second: Vec<&str> = lines
        .next()
        .ok_or("missing second line")?
        .split_whitespace()
        .collect();
    if first.len() != 3 {
        return Err("first line must hold width, height and limit".into());
    }
    if second.len() != 4 {
        return Err("second line must hold x_min, x_max, y_min and y_max".into());
    }
    let int = |s: &str, name: &str, max: u32| -> Result<u32, String> {
        let v: u32 = s
            .parse()
            .map_err(|_| format!("{name} is not a whole number: {s}"))?;
        if v < 1 || v > max {
            return Err(format!("{name} must be between 1 and {max}: {v}"));
        }
        Ok(v)
    };
    let real = |s: &str, name: &str| -> Result<f64, String> {
        let v: f64 = s
            .parse()
            .map_err(|_| format!("{name} is not a number: {s}"))?;
        if !v.is_finite() {
            return Err(format!("{name} must be finite: {s}"));
        }
        Ok(v)
    };
    let input = Input {
        width: int(first[0], "width", 1024)?,
        height: int(first[1], "height", 1024)?,
        limit: int(first[2], "limit", 1000)?,
        x_min: real(second[0], "x_min")?,
        x_max: real(second[1], "x_max")?,
        y_min: real(second[2], "y_min")?,
        y_max: real(second[3], "y_max")?,
    };
    if input.x_min >= input.x_max {
        return Err("x_min must be less than x_max".into());
    }
    if input.y_min >= input.y_max {
        return Err("y_min must be less than y_max".into());
    }
    Ok(input)
}

/// Point coordinates along one axis, computed in double precision.
fn axis(min: f64, max: f64, count: u32) -> Vec<f32> {
    let step = (max - min) / f64::from(count);
    (0..count)
        .map(|k| (min + (f64::from(k) + 0.5) * step) as f32)
        .collect()
}

/// Runs the escape-time kernel on the GPU and returns one time per point, row by row.
fn escape_times(input: &Input) -> Result<Vec<u32>, String> {
    pollster::block_on(async {
        let instance = wgpu::Instance::new(&wgpu::InstanceDescriptor::from_env_or_default());
        let adapter = instance
            .request_adapter(&wgpu::RequestAdapterOptions {
                power_preference: wgpu::PowerPreference::HighPerformance,
                force_fallback_adapter: false,
                compatible_surface: None,
            })
            .await
            .map_err(|e| format!("no GPU adapter: {e}"))?;
        let (device, queue) = adapter
            .request_device(&wgpu::DeviceDescriptor {
                label: None,
                required_features: wgpu::Features::empty(),
                required_limits: wgpu::Limits::downlevel_defaults(),
                memory_hints: wgpu::MemoryHints::default(),
                trace: wgpu::Trace::Off,
            })
            .await
            .map_err(|e| format!("no GPU device: {e}"))?;

        let xs = axis(input.x_min, input.x_max, input.width);
        let ys = axis(input.y_min, input.y_max, input.height);
        let params = [input.width, input.height, input.limit, 0u32];
        let count = (input.width * input.height) as usize;
        let size = (count * std::mem::size_of::<u32>()) as wgpu::BufferAddress;

        let params_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
            label: Some("params"),
            contents: bytemuck::cast_slice(&params),
            usage: wgpu::BufferUsages::UNIFORM,
        });
        let xs_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
            label: Some("xs"),
            contents: bytemuck::cast_slice(&xs),
            usage: wgpu::BufferUsages::STORAGE,
        });
        let ys_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
            label: Some("ys"),
            contents: bytemuck::cast_slice(&ys),
            usage: wgpu::BufferUsages::STORAGE,
        });
        let times_buf = device.create_buffer(&wgpu::BufferDescriptor {
            label: Some("times"),
            size,
            usage: wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC,
            mapped_at_creation: false,
        });
        let readback = device.create_buffer(&wgpu::BufferDescriptor {
            label: Some("readback"),
            size,
            usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
            mapped_at_creation: false,
        });

        let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
            label: Some("escape"),
            source: wgpu::ShaderSource::Wgsl(SHADER.into()),
        });
        let pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
            label: Some("escape"),
            layout: None,
            module: &module,
            entry_point: Some("main"),
            compilation_options: Default::default(),
            cache: None,
        });
        let bind_group = device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: None,
            layout: &pipeline.get_bind_group_layout(0),
            entries: &[
                wgpu::BindGroupEntry {
                    binding: 0,
                    resource: params_buf.as_entire_binding(),
                },
                wgpu::BindGroupEntry {
                    binding: 1,
                    resource: xs_buf.as_entire_binding(),
                },
                wgpu::BindGroupEntry {
                    binding: 2,
                    resource: ys_buf.as_entire_binding(),
                },
                wgpu::BindGroupEntry {
                    binding: 3,
                    resource: times_buf.as_entire_binding(),
                },
            ],
        });

        let mut encoder = device.create_command_encoder(&Default::default());
        {
            let mut pass = encoder.begin_compute_pass(&Default::default());
            pass.set_pipeline(&pipeline);
            pass.set_bind_group(0, &bind_group, &[]);
            pass.dispatch_workgroups(
                input.width.div_ceil(WORKGROUP),
                input.height.div_ceil(WORKGROUP),
                1,
            );
        }
        encoder.copy_buffer_to_buffer(&times_buf, 0, &readback, 0, size);
        queue.submit(Some(encoder.finish()));

        let slice = readback.slice(..);
        let (tx, rx) = std::sync::mpsc::channel();
        slice.map_async(wgpu::MapMode::Read, move |r| {
            let _ = tx.send(r);
        });
        device
            .poll(wgpu::PollType::Wait)
            .map_err(|e| format!("GPU poll failed: {e}"))?;
        rx.recv()
            .map_err(|e| format!("GPU readback lost: {e}"))?
            .map_err(|e| format!("GPU readback failed: {e}"))?;
        let times = bytemuck::cast_slice::<u8, u32>(&slice.get_mapped_range()).to_vec();
        readback.unmap();
        Ok(times)
    })
}

fn main() -> ExitCode {
    let Some(path) = std::env::args().nth(1) else {
        eprintln!("usage: escape_time <input-file>");
        return ExitCode::FAILURE;
    };
    let input = match std::fs::read_to_string(&path)
        .map_err(|e| format!("cannot read {path}: {e}"))
        .and_then(|t| parse_input(&t))
    {
        Ok(input) => input,
        Err(e) => {
            eprintln!("error: {e}");
            return ExitCode::FAILURE;
        }
    };
    let times = match escape_times(&input) {
        Ok(times) => times,
        Err(e) => {
            eprintln!("error: {e}");
            return ExitCode::FAILURE;
        }
    };

    let limit = u64::from(input.limit);
    let mut inside = 0u64;
    let mut bins = [0u64; 8];
    let mut total = 0u64;
    let mut escaped = 0u64;
    for &n in &times {
        let n = u64::from(n);
        if n >= limit {
            inside += 1;
        } else {
            bins[(8 * n / limit) as usize] += 1;
            total += n;
            escaped += 1;
        }
    }
    let mean = if escaped == 0 {
        0.0
    } else {
        total as f64 / escaped as f64
    };

    println!("INSIDE {inside}");
    for (k, count) in bins.iter().enumerate() {
        println!("BIN {k} {count}");
    }
    println!("MEAN {mean:.3}");
    ExitCode::SUCCESS
}

