                power_preference: wgpu::PowerPreference::HighPerformance,
                force_fallback_adapter: false,
                compatible_surface: None,
            })
            .await
            .map_err(|e| format!("no GPU adapter: {e}"))?;
        let (device, queue) = adapter
            .request_device(&wgpu::DeviceDescriptor {
                label: None,
                required_features: wgpu::Features::empty(),
                required_limits: wgpu::Limits::downlevel_defaults(),
                memory_hints: wgpu::MemoryHints::default(),
                trace: wgpu::Trace::Off,
            })
            .await
            .map_err(|e| format!("no GPU device: {e}"))?;

        let xs = axis(input.x_min, input.x_max, input.width);
        let ys = axis(input.y_min, input.y_max, input.height);
        let params = [input.width, input.height, input.limit, 0u32];
        let count = (input.width * input.height) as usize;
        let size = (count * std::mem::size_of::<u32>()) as wgpu::BufferAddress;

        let params_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
            label: Some("params"),
            contents: bytemuck::cast_slice(&params),
            usage: wgpu::BufferUsages::UNIFORM,
        });
        let xs_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
            label: Some("xs"),
            contents: bytemuck::cast_slice(&xs),
            usage: wgpu::BufferUsages::STORAGE,
        });
        let ys_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
            label: Some("ys"),
            contents: bytemuck::cast_slice(&ys),
            usage: wgpu::BufferUsages::STORAGE,
        });
        let times_buf = device.create_buffer(&wgpu::BufferDescriptor {
            label: Some("times"),
            size,
            usage: wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC,
            mapped_at_creation: false,
        });
        let readback = device.create_buffer(&wgpu::BufferDescriptor {
            label: Some("readback"),
            size,
            usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
            mapped_at_creation: false,
        });

        let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
            label: Some("escape"),
            source: wgpu::ShaderSource::Wgsl(SHADER.into()),
        });
        let pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
            label: Some("escape"),
            layout: None,
            module: &module,
            entry_point: Some("main"),
            compilation_options: Default::default(),
            cache: None,
        });
        let bind_group = device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: None,
            layout: &pipeline.get_bind_group_layout(0),
            entries: &[
                wgpu::BindGroupEntry {
                    binding: 0,
                    resource: params_buf.as_entire_binding(),
                },
                wgpu::BindGroupEntry {
                    binding: 1,
                    resource: xs_buf.as_entire_binding(),
                },
                wgpu::BindGroupEntry {
                    binding: 2,
                    resource: ys_buf.as_entire_binding(),
                },
                wgpu::BindGroupEntry {
                    binding: 3,
                    resource: times_buf.as_entire_binding(),
                },
            ],
        });

        let mut encoder = device.create_command_encoder(&Default::default());
        {
            let mut pass = encoder.begin_compute_pass(&Default::default());
            pass.set_pipeline(&pipeline);
            pass.set_bind_group(0, &bind_group, &[]);
            pass.dispatch_workgroups(
                input.width.div_ceil(WORKGROUP),
                input.height.div_ceil(WORKGROUP),
                1,
            );
        }
        encoder.copy_buffer_to_buffer(&times_buf, 0, &readback, 0, size);
        queue.submit(Some(encoder.finish()));

        let slice = readback.slice(..);
        let (tx, rx) = std::sync::mpsc::channel();
        slice.map_async(wgpu::MapMode::Read, move |r| {
            let _ = tx.send(r);
        });
        device
            .poll(wgpu::PollType::Wait)
            .map_err(|e| format!("GPU poll failed: {e}"))?;
        rx.recv()
            .map_err(|e| format!("GPU readback lost: {e}"))?
            .map_err(|e| format!("GPU readback failed: {e}"))?;
        let times = bytemuck::cast_slice::<u8, u32>(&slice.get_mapped_range()).to_vec();
        readback.unmap();
        Ok(times)
    })
}

fn main() -> ExitCode {
    let Some(path) = std::env::args().nth(1) else {
        eprintln!("usage: escape_time <input-file>");
        return ExitCode::FAILURE;
    };
    let input = match std::fs::read_to_string(&path)
        .map_err(|e| format!("cannot read {path}: {e}"))
        .and_then(|t| parse_input(&t))
    {
        Ok(input) => input,
        Err(e) => {
            eprintln!("error: {e}");
            return ExitCode::FAILURE;
        }
    };
    let times = match escape_times(&input) {
        Ok(times) => times,
        Err(e) => {
            eprintln!("error: {e}");
            return ExitCode::FAILURE;
        }
    };

    let limit = u64::from(input.limit);
    let mut inside = 0u64;
    let mut bins = [0u64; 8];
    let mut total = 0u64;
    let mut escaped = 0u64;
    for &n in &times {
        let n = u64::from(n);
        if n >= limit {
            inside += 1;
        } else {
            bins[(8 * n / limit) as usize] += 1;
            total += n;
            escaped += 1;
        }
    }
    let mean = if escaped == 0 {
        0.0
    } else {
        total as f64 / escaped as f64
    };

    println!("INSIDE {inside}");
    for (k, count) in bins.iter().enumerate() {
        println!("BIN {k} {count}");
    }
    println!("MEAN {mean:.3}");
    ExitCode::SUCCESS
}
